create extension if not exists "pgcrypto";
create type public.app_role as enum ('SUPER_ADMIN','OWNER','MANAGER','CASHIER');
create type public.subscription_status as enum ('TRIAL','ACTIVE','EXPIRED','SUSPENDED');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tenants (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, address text, whatsapp text, owner_id uuid not null references public.profiles(id), timezone text not null default 'Asia/Jakarta', currency text not null default 'IDR', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.branches (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, name text not null, address text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(tenant_id,name));
create table public.tenant_users (tenant_id uuid not null references public.tenants(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.app_role not null default 'CASHIER', branch_id uuid references public.branches(id), is_active boolean not null default true, created_at timestamptz not null default now(), primary key(tenant_id,user_id));
create table public.subscription_plans (id text primary key, name text not null, max_branches int, max_users int, trial_days int not null default 0);
create table public.subscriptions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, plan_id text not null references public.subscription_plans(id), start_date date not null, end_date date not null, status public.subscription_status not null default 'TRIAL', created_at timestamptz not null default now());
create index branches_tenant_idx on public.branches(tenant_id); create index tenant_users_user_idx on public.tenant_users(user_id); create index subscriptions_tenant_idx on public.subscriptions(tenant_id);
create or replace function public.is_tenant_member(target_tenant uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.tenant_users where tenant_id=target_tenant and user_id=auth.uid() and is_active) or exists(select 1 from public.tenants where id=target_tenant and owner_id=auth.uid()); $$;
alter table public.tenants enable row level security; alter table public.branches enable row level security; alter table public.tenant_users enable row level security; alter table public.subscriptions enable row level security;
create policy tenants_member on public.tenants for select using (public.is_tenant_member(id)); create policy tenants_owner_update on public.tenants for update using (owner_id=auth.uid());
create policy branches_member on public.branches for all using (public.is_tenant_member(tenant_id)) with check (public.is_tenant_member(tenant_id));
create policy tenant_users_member on public.tenant_users for select using (public.is_tenant_member(tenant_id)); create policy tenant_users_owner_write on public.tenant_users for all using (exists(select 1 from public.tenants t where t.id=tenant_id and t.owner_id=auth.uid())) with check (public.is_tenant_member(tenant_id));
create policy subscriptions_member on public.subscriptions for select using (public.is_tenant_member(tenant_id));
insert into public.subscription_plans(id,name,max_branches,max_users,trial_days) values ('TRIAL','Trial',1,2,14),('BASIC','Basic',1,2,0),('PRO','Pro',3,10,0),('BUSINESS','Business',null,null,0) on conflict do nothing;
